#### Phase 1: Shadow Properties Approach (Weeks 1-2)

1. **Define Extension DbContext**:
   ```csharp
   public class TexasExtensionContext : DbContext
   {
       public TexasExtensionContext(DbContextOptions<TexasExtensionContext> options)
           : base(options) { }

       protected override void OnModelCreating(ModelBuilder modelBuilder)
       {
           // Add shadow properties with "Ext_" prefix
           modelBuilder.Entity<Claim>()
               .Property<string>("Ext_TexasTrackingNumber")
               .HasMaxLength(50);

           modelBuilder.Entity<Claim>()
               .Property<DateTime?>("Ext_TexasProcessedDate");

           modelBuilder.Entity<Claim>()
               .HasIndex("Ext_TexasTrackingNumber");
       }
   }
   ```

2. **Create Migration**:
   ```bash
   dotnet ef migrations add AddTexasClaimExtensions --context TexasExtensionContext
   ```

3. **Create Helper Extension Methods**:
   ```csharp
   public static class TexasClaimExtensions
   {
       public static void SetTexasTrackingNumber(this DbContext context, Claim claim, string value)
       {
           context.Entry(claim).Property("Ext_TexasTrackingNumber").CurrentValue = value;
       }

       public static string GetTexasTrackingNumber(this DbContext context, Claim claim)
       {
           return context.Entry(claim).Property("Ext_TexasTrackingNumber").CurrentValue as string;
       }
   }
   ```

