#### Phase 2: Extension Tables Approach (Weeks 3-4)

4. **Define Extension Entity**:
   ```csharp
   public class CaliforniaProviderExtension
   {
       public int ProviderId { get; set; }
       public string CaliforniaLicenseNumber { get; set; }
       public DateTime CaliforniaLicenseExpiry { get; set; }
       public string CaliforniaMedicaidNumber { get; set; }
       public List<string> CaliforniaSpecializations { get; set; }

       // Navigation to core entity
       public Provider Provider { get; set; }
   }
   ```

5. **Configure Extension Context**:
   ```csharp
   public class CaliforniaExtensionContext : DbContext
   {
       public DbSet<CaliforniaProviderExtension> ProviderExtensions { get; set; }

       protected override void OnModelCreating(ModelBuilder modelBuilder)
       {
           modelBuilder.Entity<CaliforniaProviderExtension>(entity =>
           {
               entity.HasKey(e => e.ProviderId);
               entity.ToTable("CaliforniaProviderExtensions");

               entity.HasOne(e => e.Provider)
                   .WithOne()
                   .HasForeignKey<CaliforniaProviderExtension>(e => e.ProviderId)
                   .OnDelete(DeleteBehavior.Cascade);

               entity.Property(e => e.CaliforniaSpecializations)
                   .HasConversion(
                       v => JsonSerializer.Serialize(v, (JsonSerializerOptions)null),
                       v => JsonSerializer.Deserialize<List<string>>(v, (JsonSerializerOptions)null));
           });
       }
   }
   ```

6. **Generate and Apply Migration**:
   ```bash
   dotnet ef migrations add AddCaliforniaProviderExtensions --context CaliforniaExtensionContext
   dotnet ef database update --context CaliforniaExtensionContext
   ```

