#### Example 1: Shadow Properties with Indexing

```csharp
public class MichiganExtensionContext : DbContext
{
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Add shadow properties to Claim entity
        modelBuilder.Entity<Claim>(entity =>
        {
            entity.Property<string>("Ext_MichiganBatchId")
                .HasMaxLength(20)
                .IsRequired(false);

            entity.Property<decimal?>("Ext_MichiganStateSupplementAmount");

            entity.Property<DateTime?>("Ext_MichiganProcessedDate");

            // Composite index on shadow properties
            entity.HasIndex("Ext_MichiganBatchId", "Ext_MichiganProcessedDate")
                .HasDatabaseName("IX_Michigan_Batch_Date");
        });
    }
}

// Usage
public class MichiganClaimProcessor
{
    private readonly MichiganExtensionContext _context;

    public async Task ProcessClaimAsync(Claim claim, string batchId)
    {
        _context.Entry(claim).Property("Ext_MichiganBatchId").CurrentValue = batchId;
        _context.Entry(claim).Property("Ext_MichiganProcessedDate").CurrentValue = DateTime.UtcNow;
        await _context.SaveChangesAsync();
    }

    public async Task<List<Claim>> GetClaimsByBatchAsync(string batchId)
    {
        return await _context.Claims
            .Where(c => EF.Property<string>(c, "Ext_MichiganBatchId") == batchId)
            .OrderBy(c => EF.Property<DateTime?>(c, "Ext_MichiganProcessedDate"))
            .ToListAsync();
    }
}
```

