#### Example 2: Extension Table with Complex Types

```csharp
public class NewYorkClaimExtension
{
    public int ClaimId { get; set; }
    public string NewYorkAuthorizationNumber { get; set; }
    public List<string> NewYorkDiagnosisCodes { get; set; }
    public Dictionary<string, decimal> NewYorkLineItemAdjustments { get; set; }
    public NewYorkAuditInfo AuditInfo { get; set; }

    public Claim Claim { get; set; }
}

public class NewYorkAuditInfo
{
    public string ReviewedBy { get; set; }
    public DateTime ReviewDate { get; set; }
    public string Notes { get; set; }
}

public class NewYorkExtensionContext : DbContext
{
    public DbSet<NewYorkClaimExtension> ClaimExtensions { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<NewYorkClaimExtension>(entity =>
        {
            entity.HasKey(e => e.ClaimId);
            entity.ToTable("NewYorkClaimExtensions");

            // 1:1 relationship
            entity.HasOne(e => e.Claim)
                .WithOne()
                .HasForeignKey<NewYorkClaimExtension>(e => e.ClaimId)
                .OnDelete(DeleteBehavior.Cascade);

            // JSON column for list
            entity.Property(e => e.NewYorkDiagnosisCodes)
                .HasColumnType("nvarchar(max)")
                .HasConversion(
                    v => JsonSerializer.Serialize(v, (JsonSerializerOptions)null),
                    v => JsonSerializer.Deserialize<List<string>>(v, (JsonSerializerOptions)null));

            // JSON column for dictionary
            entity.Property(e => e.NewYorkLineItemAdjustments)
                .HasColumnType("nvarchar(max)")
                .HasConversion(
                    v => JsonSerializer.Serialize(v, (JsonSerializerOptions)null),
                    v => JsonSerializer.Deserialize<Dictionary<string, decimal>>(v, (JsonSerializerOptions)null));

            // Owned type for nested object
            entity.OwnsOne(e => e.AuditInfo, audit =>
            {
                audit.Property(a => a.ReviewedBy).HasMaxLength(100);
                audit.Property(a => a.Notes).HasMaxLength(500);
            });
        });
    }
}
```

