[patterns/application/extensions/PTN-APP-EXT-007-entity-framework-extensibility-pattern.md#example-3-coordinated-multi-context-transaction]

#### Example 3: Coordinated Multi-Context Transaction

```csharp
public class TexasClaimService
{
    private readonly ProductDbContext _productContext;
    private readonly TexasExtensionContext _texasContext;

    public async Task ProcessClaimWithExtensionAsync(
        Claim claim, TexasClaimExtension extension)
    {
        // Start transaction on product context
        await using var transaction = await _productContext.Database
            .BeginTransactionAsync(IsolationLevel.ReadCommitted);

        try
        {
            // Update core claim
            claim.Status = ClaimStatus.Processed;
            claim.ProcessedDate = DateTime.UtcNow;
            _productContext.Update(claim);
            await _productContext.SaveChangesAsync();

            // Use same transaction for extension context
            await _texasContext.Database.UseTransactionAsync(transaction.GetDbTransaction());

            // Update extension data
            extension.TexasVerificationStatus = "Verified";
            _texasContext.Update(extension);
            await _texasContext.SaveChangesAsync();

            // Commit both contexts together
            await transaction.CommitAsync();
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            throw new ClaimProcessingException("Failed to process claim with extension", ex);
        }
    }
}
```

