#### Example 4: Migration Configuration

```csharp
// In extension startup
public class FloridaExtensionStartup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddDbContext<FloridaExtensionContext>(options =>
        {
            options.UseSqlServer(
                connectionString,
                sqlOptions =>
                {
                    sqlOptions.MigrationsHistoryTable(
                        "__FloridaExtensionMigrationsHistory",
                        "extension");
                    sqlOptions.MigrationsAssembly("FloridaExtension");
                });
        });
    }

    public async Task ApplyMigrationsAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var context = scope.ServiceProvider.GetRequiredService<FloridaExtensionContext>();

        // Apply pending migrations
        await context.Database.MigrateAsync();
    }
}
```

