### Real-World Example 1: Ohio Claims Processing with Shadow Properties

**Context**: Ohio requires tracking additional processing timestamps and batch identifiers not in the core product.

**Implementation**:

```csharp
public class OhioExtensionContext : DbContext
{
    public DbSet<Claim> Claims { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Claim>(entity =>
        {
            // Shadow properties for Ohio-specific tracking
            entity.Property<string>("Ext_OhioBatchNumber")
                .HasMaxLength(30);
            entity.Property<DateTime?>("Ext_OhioReceivedDate");
            entity.Property<DateTime?>("Ext_OhioCompletedDate");
            entity.Property<string>("Ext_OhioProcessorId")
                .HasMaxLength(50);

            // Index for batch queries
            entity.HasIndex("Ext_OhioBatchNumber", "Ext_OhioReceivedDate")
                .HasDatabaseName("IX_Ohio_Batch_Received");
        });
    }
}

public class OhioClaimProcessor
{
    private readonly OhioExtensionContext _context;
    private readonly ILogger<OhioClaimProcessor> _logger;

    public async Task ProcessBatchAsync(List<Claim> claims, string batchNumber)
    {
        foreach (var claim in claims)
        {
            _context.Entry(claim).Property("Ext_OhioBatchNumber").CurrentValue = batchNumber;
            _context.Entry(claim).Property("Ext_OhioReceivedDate").CurrentValue = DateTime.UtcNow;
            _context.Entry(claim).Property("Ext_OhioProcessorId").CurrentValue = Environment.MachineName;
        }

        await _context.SaveChangesAsync();
        _logger.LogInformation("Processed {Count} claims for batch {Batch}", claims.Count, batchNumber);
    }

    public async Task<BatchSummary> GetBatchSummaryAsync(string batchNumber)
    {
        var claims = await _context.Claims
            .Where(c => EF.Property<string>(c, "Ext_OhioBatchNumber") == batchNumber)
            .ToListAsync();

        return new BatchSummary
        {
            BatchNumber = batchNumber,
            TotalClaims = claims.Count,
            ProcessedClaims = claims.Count(c =>
                _context.Entry(c).Property("Ext_OhioCompletedDate").CurrentValue != null),
            OldestReceived = claims.Min(c =>
                _context.Entry(c).Property("Ext_OhioReceivedDate").CurrentValue as DateTime?)
        };
    }
}
```

