### Real-World Example 2: Pennsylvania Provider Extensions with Separate Table

**Context**: Pennsylvania requires extensive provider licensing data including multiple license types, certifications, and inspection records.

**Implementation**:

```csharp
public class PennsylvaniaProviderExtension
{
    public int ProviderId { get; set; }
    public string PennsylvaniaMedicaidId { get; set; }
    public List<PennsylvaniaLicense> Licenses { get; set; }
    public List<PennsylvaniaInspection> Inspections { get; set; }
    public PennsylvaniaQualityRating QualityRating { get; set; }

    public Provider Provider { get; set; }
}

public class PennsylvaniaLicense
{
    public int Id { get; set; }
    public int ProviderId { get; set; }
    public string LicenseType { get; set; }
    public string LicenseNumber { get; set; }
    public DateTime IssueDate { get; set; }
    public DateTime ExpiryDate { get; set; }
    public string Status { get; set; }
}

public class PennsylvaniaInspection
{
    public int Id { get; set; }
    public int ProviderId { get; set; }
    public DateTime InspectionDate { get; set; }
    public string InspectorId { get; set; }
    public string Result { get; set; }
    public List<string> Findings { get; set; }
}

public class PennsylvaniaQualityRating
{
    public decimal OverallScore { get; set; }
    public int StarRating { get; set; }
    public DateTime LastReviewDate { get; set; }
}

public class PennsylvaniaExtensionContext : DbContext
{
    public DbSet<PennsylvaniaProviderExtension> ProviderExtensions { get; set; }
    public DbSet<PennsylvaniaLicense> Licenses { get; set; }
    public DbSet<PennsylvaniaInspection> Inspections { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<PennsylvaniaProviderExtension>(entity =>
        {
            entity.HasKey(e => e.ProviderId);
            entity.ToTable("PennsylvaniaProviderExtensions");

            entity.HasOne(e => e.Provider)
                .WithOne()
                .HasForeignKey<PennsylvaniaProviderExtension>(e => e.ProviderId)
                .OnDelete(DeleteBehavior.Cascade);

            entity.OwnsOne(e => e.QualityRating, rating =>
            {
                rating.Property(r => r.OverallScore).HasColumnType("decimal(5,2)");
            });

            entity.HasMany(e => e.Licenses)
                .WithOne()
                .HasForeignKey(l => l.ProviderId);

            entity.HasMany(e => e.Inspections)
                .WithOne()
                .HasForeignKey(i => i.ProviderId);
        });

        modelBuilder.Entity<PennsylvaniaLicense>(entity =>
        {
            entity.ToTable("PennsylvaniaProviderLicenses");
            entity.HasIndex(l => new { l.ProviderId, l.LicenseType });
            entity.Property(l => l.Status).HasMaxLength(20);
        });

        modelBuilder.Entity<PennsylvaniaInspection>(entity =>
        {
            entity.ToTable("PennsylvaniaProviderInspections");
            entity.HasIndex(i => i.InspectionDate);

            entity.Property(i => i.Findings)
                .HasConversion(
                    v => JsonSerializer.Serialize(v, (JsonSerializerOptions)null),
                    v => JsonSerializer.Deserialize<List<string>>(v, (JsonSerializerOptions)null));
        });
    }
}
```

**Usage in Extension**:

```csharp
public class PennsylvaniaProviderValidator
{
    private readonly PennsylvaniaExtensionContext _context;

    public async Task<ValidationResult> ValidateProviderAsync(int providerId)
    {
        var extension = await _context.ProviderExtensions
            .Include(e => e.Licenses)
            .Include(e => e.Inspections)
            .FirstOrDefaultAsync(e => e.ProviderId == providerId);

        if (extension == null)
            return ValidationResult.Fail("No Pennsylvania extension data found");

        // Check for active license
        var hasActiveLicense = extension.Licenses.Any(l =>
            l.Status == "Active" && l.ExpiryDate > DateTime.UtcNow);

        if (!hasActiveLicense)
            return ValidationResult.Fail("No active Pennsylvania license");

        // Check recent inspection
        var recentInspection = extension.Inspections
            .OrderByDescending(i => i.InspectionDate)
            .FirstOrDefault();

        if (recentInspection == null ||
            recentInspection.InspectionDate < DateTime.UtcNow.AddYears(-2))
            return ValidationResult.Fail("Missing recent inspection");

        if (recentInspection.Result != "Passed")
            return ValidationResult.Fail($"Failed inspection: {recentInspection.Result}");

        // Check quality rating
        if (extension.QualityRating.StarRating < 3)
            return ValidationResult.Fail("Quality rating below minimum");

        return ValidationResult.Success();
    }
}
```

